#include<bits/stdc++.h>
using namespace std;

struct TreeNode{
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x):val(x),left(nullptr),right(nullptr){}
};

TreeNode* buildTree(vector<string> &tokens){
    TreeNode* root;
    root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    int idx = 1;

    while(!q.empty()&&idx<tokens.size()){
        TreeNode *node;
        node = q.front();
        q.pop();
        if(tokens[idx] != "null"){
            node->left = new TreeNode(stoi(tokens[idx]));
            q.push(node->left);
        }
        idx++;
        if(idx<tokens.size()&&tokens[idx] != "null"){
            node->right = new TreeNode(stoi(tokens[idx]));
            q.push(node->right);
        }
        idx++;

    }
    return root;
}



int Getbest(TreeNode* node,vector<int> &result){
    if(!node) return 0;
    int l,r ;
    l = r = -1001; 
    if(node->left) l = Getbest(node->left,result);
    if(node->right) r = Getbest(node->right,result);
    int value = (node->val) + max(max(l,r),0);
    result.push_back(value);
    return value;
}

int main(){
    int k;
    cin>>k;
    vector<string> tokens(k);
    for(int i = 0;i<k;i++){
        cin>> tokens[i];
    }
    TreeNode* root = buildTree(tokens);
    vector<int> result(k,-1001);
    int root_best = Getbest(root,result);
    int best = root_best;
    for(int j =0;j<k;j++){
        best = max(best,result[j]);
    }
    cout<<best;

    return 0;
}
